# kind=url 的 url 模板可用 {url} 与 {title} 占位；kind=copy 点击后复制链接并提示 message
SHARE_TARGETS = {
    "copylink": {"label": "复制链接", "kind": "copy", "message": "链接已复制到剪贴板。"},
    "wechat": {"label": "微信", "kind": "copy", "message": "链接已复制，可粘贴到微信分享。"},
    "weibo": {"label": "微博", "kind": "url", "url": "https://service.weibo.com/share/share.php?url={url}&title={title}"},
    "xiaohongshu": {"label": "小红书", "kind": "copy", "message": "链接已复制，可粘贴到小红书 App 分享。"},
    "threads": {"label": "Threads", "kind": "url", "url": "https://www.threads.net/intent/post?text={url}"},
    "x": {"label": "X（Twitter）", "kind": "url", "url": "https://twitter.com/share?url={url}&text={title}"},
    "facebook": {"label": "Facebook", "kind": "url", "url": "https://www.facebook.com/sharer.php?u={url}"},
    "reddit": {"label": "Reddit", "kind": "url", "url": "https://reddit.com/submit?url={url}&title={title}"},
    "hackernews": {"label": "Hacker News", "kind": "url", "url": "https://news.ycombinator.com/submitlink?u={url}&t={title}"},
    "email": {"label": "邮件", "kind": "url", "url": "mailto:?subject={title}&body={url}"},
}

DEFAULT_ORDER = list(SHARE_TARGETS)


def available_names():
    return list(SHARE_TARGETS)


def prepare_share_targets(request, post, rows):
    """把数据库里的显隐/排序与注册表合成模板可直接渲染的列表。"""
    if rows:
        names = [row.name for row in rows]
    else:
        names = DEFAULT_ORDER
    url = quote(request.build_absolute_uri(), safe="")
    title = quote(post.title, safe="")
    targets = []
    for name in names:
        spec = SHARE_TARGETS.get(name)
        if not spec:
            continue
        icon = ICONS.get(name)
        if not icon:
            # 注册表与图标由人工同步维护，缺图标的条目直接跳过，避免渲染出空白按钮
            continue
        target = {
            "name": name,
            "label": spec["label"],
            "kind": spec["kind"],
            "icon": icon,
        }
        if spec["kind"] == "copy":
            target["message"] = spec.get("message", "链接已复制到剪贴板。")
        else:
            target["href"] = spec["url"].format(url=url, title=title)
        targets.append(target)
    return targets
